window.AUTH=window.AUTH||{};window.AUTH["21-147"]={"d":"21-147","id":"2021/21-147","n":"Egbert v. Boule","briefs":[{"k":"petitioner","label":"Brief of petitioner Erik Egbert","date":"2021-12-20","url":"https://www.supremecourt.gov/DocketPDF/21/21-147/205799/20211220155114719_2021.12.20%20-%20Egbert%20Brief.pdf","side":"pet","n":87},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2021-12-23","url":"https://www.supremecourt.gov/DocketPDF/21/21-147/206394/20211223160402183_21-147tsacUnitedStates.pdf","side":"us","n":61},{"k":"reply","label":"Reply of petitioner Erik Egbert","date":"2022-02-18","url":"https://www.supremecourt.gov/DocketPDF/21/21-147/214516/20220218123712110_Egbert%20Reply%20Brief.pdf","side":"pet","n":49}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us1r37_7l48.pdf","tr":true,"items":[{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"op":3,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"16, 17","2":"3, 6"}},{"t":"case","label":"Alvarez v. ICE","cite":"818 F.3d 1194","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/818/1194/","by":{"0":"29"}},{"t":"case","label":"Am. Elec. Power Co. v. Connecticut","cite":"564 U.S. 410","y":2011,"id":"2010/10-174","sc":1,"sum":"The Court held that held the Clean Air Act bars suits by governmental bodies and private parties seeking to curb emissions from utilities via the federal common law.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"op":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"0":"18","1":"16, 19, 20","2":"11"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20"}},{"t":"case","label":"Bendix Autolite Corp. v. Midwesco Enters.","cite":"486 U.S. 888","y":1988,"id":"1987/87-367","sc":1,"sum":"The Ohio tolling statute violates the Commerce Clause, since it imposes an impermissible burden on interstate commerce. To gain the protection of the limitations period, appellee-which has no corporate office in Ohio and is not registered to do business there-would have had to appoint a resident agent for service of process in Ohio and subject itself to the Ohio courts' general jurisdiction. Ohio's statutory scheme …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Bistrian v. Levi","cite":"912 F.3d 79","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/912/79/","by":{"0":"19, 26","1":"21"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Fed. Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"op":199,"ar":69,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"0":"passim","1":"1, 2, 8, 11, 12, 13","2":"passim"}},{"t":"case","label":"Borowski v. Bechelli","cite":"772 F. App’x 338","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/772/338/","by":{"0":"26"}},{"t":"case","label":"Bush v. Lucas","cite":"462 U.S. 367","y":1983,"id":"1982/81-469","sc":1,"op":12,"sum":"Not under the CSC regulations. The federal judiciary, pursuant to its common law authority, has the power to recognize new causes of action in absence of, or to supplement, statutory remedies unless Congress has expressly indicated its relief is to be exclusive.","sumSrc":"Oyez","by":{"0":"26, 28, 32, 33","1":"9, 13, 20, 23, 24, 25","2":"15"}},{"t":"case","label":"Butler v. S. Porter","cite":"999 F.3d 287","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/999/287/","by":{"0":"26"}},{"t":"case","label":"Callahan v. Fed. Bureau of Prisons","cite":"965 F.3d 520","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/965/520/","by":{"0":"19, 24, 26","2":"22"}},{"t":"case","label":"Cameron v. IRS","cite":"773 F.2d 126","y":1985,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/773/126/","by":{"0":"33"}},{"t":"case","label":"Cantú v. Moody","cite":"933 F.3d 414","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/933/414/","by":{"0":"25"}},{"t":"case","label":"Carlson v. Green","cite":"446 U.S. 14","y":1980,"id":"1979/78-1261","sc":1,"op":12,"ar":2,"sum":"Respondent brought suit in Federal District Court in Indiana on behalf of her deceased son's estate, alleging that her son while a prisoner in a federal prison in Indiana suffered personal injuries from which he died because petitioner prison officials violated, inter alia, his Eighth Amendment rights by failing to give him proper medical attention. Asserting jurisdiction under 28 U. S. C. § 1331 (a), respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"12, 33","2":"2, 9, 10, 11"}},{"t":"case","label":"Centurion Props. III, LLC v. Chi. Title Ins. Co.","cite":"375 P.3d 651","y":2016,"court":"Wash.","url":"https://www.courtlistener.com/c/P.3d/375/651/","by":{"0":"33"}},{"t":"case","label":"City of Milwaukee v. Illinois","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"sum":"In original proceedings brought by respondent State of Illinois, alleging that petitioners-the city of Milwaukee, its Sewerage Commission, and Milwaukee County's Metropolitan Sewerage Commission-and other Wisconsin cities were polluting Lake Michigan because of overflows of untreated sewage from their sewer systems and discharges of inadequately treated sewage from their treatment plants, this Court recognized the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Comcast Corp. v. Nat’l Ass’n of Afr. Am.-Owned Media","cite":"140 S. Ct. 1009","y":2020,"id":"2019/18-1171","sc":1,"sum":"The Court held that a claim of race discrimination under 42 U.S.C. § 1981 requires that the plaintiff show that race was a but-for cause of the plaintiff's injury.","sumSrc":"Oyez","by":{"0":"17","2":"6"}},{"t":"case","label":"Corr. Servs. Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"op":10,"sum":"Noting that remedies available to the plaintiff were “at least as great, and in many respects greater, than anything that could be had under Page Proof Pending Publication Bivens”.","sumSrc":"opinion","by":{"0":"15, 35, 40","1":"13, 14","2":"9"}},{"t":"case","label":"Crawford-El v. Britton","cite":"523 U.S. 574","y":1998,"id":"1997/96-827","sc":1,"op":1,"sum":"The Court held that the Court of Appeals erred in fashioning a heightened burden of proof for unconstitutional-motive cases against public officials. \"Neither the text of [section 1983] or any other federal statute, nor the Federal Rules of Civil Procedure, provides any support for imposing the clear and convincing burden of proof on plaintiffs either at the summary judgment stage or in the trial itself,\" wrote Justice Stevens.","sumSrc":"Oyez","by":{"0":"28","1":"9, 22","2":"11, 13, 14"}},{"t":"case","label":"Daniels v. Williams","cite":"474 U.S. 327","y":1986,"id":"1985/84-5872","sc":1,"sum":"The Due Process Clause is not implicated by a state official's negligent act causing unintended loss of or injury to life, liberty, or property.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Davis v. Passman","cite":"442 U.S. 228","y":1979,"id":"1978/78-5072","sc":1,"op":9,"sum":"Relying on Bivens v. Six Unknown Federal Narcotics Agents (1971) and Butz v. Economou (1978), the Court reversed the lower court's conclusions. Both cases affirmed a citizen's right to bring suit against federal officers for constitutional violations. In this case, Passman violated Davis's rights through sexual discrimination.","sumSrc":"Oyez","by":{"0":"passim","1":"12","2":"2, 11, 14"}},{"t":"case","label":"De La Paz v. Coy","cite":"786 F.3d 367","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/786/367/","by":{"0":"29, 30, 36, 38","2":"22"}},{"t":"case","label":"Doe v. Meron","cite":"929 F.3d 153","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/929/153/","by":{"0":"26"}},{"t":"case","label":"Downie v. City of Middleburg Heights","cite":"301 F.3d 688","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/301/688/","by":{"0":"34"}},{"t":"case","label":"Duc Tan v. Le","cite":"300 P.3d 356","y":2013,"court":"Wash.","url":"https://www.courtlistener.com/c/P.3d/300/356/","by":{"0":"33"}},{"t":"case","label":"Earle v. Shreves","cite":"990 F.3d 774","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/990/774/","by":{"0":"26"}},{"t":"case","label":"Eastwood v. Cascade Broad. Co.","cite":"722 P.2d 1295","y":1986,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/722/1295/","by":{"0":"33"}},{"t":"case","label":"Edwards v. Vannoy","cite":"141 S. Ct. 1547","y":2021,"id":"2020/19-5807","sc":1,"op":1,"sum":"The jury-unanimity rule announced in Ramos v. Louisiana, 590 U. S. ___, does not apply retroactively on federal collateral review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24","2":"10"}},{"t":"case","label":"Elhady v. Unidentified CBP Agents, --- F.4th ---","cite":"2021 WL 5410758","y":2021,"court":"6th Cir.","by":{"0":"26, 29, 31, 38","1":"30"}},{"t":"case","label":"Erie R.R. Co. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"sum":"A case in which the Court overturned its prior decision in Swift v. Tyson and held that federal courts exercising diversity jurisdiction cannot create their own common law for issues that properly fall within state law.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"op":4,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","1":"13"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"sum":"The Court held that government officials are entitled to qualified immunity but not absolute immunity. Absolute immunity is only available for specific functions that require a total shield from liability.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Hartman v. Moore","cite":"547 U.S. 250","y":2006,"id":"2005/04-1495","sc":1,"op":1,"ar":2,"sum":"The Court ruled in favor of the postal inspectors, overruling the Court of Appeals. The opinion by Justice David Souter held that plaintiffs alleging retaliatory prosecution must prove that the law enforcement agents lacked probable cause. Probable cause, the Court ruled, is a crucial component of the \"chain of causation\" needed to evaluate retaliatory prosecution charges.","sumSrc":"Oyez","by":{"0":"10, 26, 28","1":"6, 8, 16, 22, 25","2":"11"}},{"t":"case","label":"Hernández v. Mesa","cite":"140 S. Ct. 735","y":2020,"id":"2019/17-1678","sc":1,"sum":"The Court held that the family of a Mexican teenager who was killed by a U.S. Border Patrol agent in a cross-border shooting cannot sue the agent for damages under the U.S. Constitution.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"Hudson Valley Black Press v. IRS","cite":"409 F.3d 106","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/409/106/","by":{"0":"33, 34","1":"25"}},{"t":"case","label":"J.I. Case Co. v. Borak","cite":"377 U.S. 426","y":1964,"id":"1963/402","sc":1,"ar":1,"sum":"Respondent, stockholder of petitioner company, brought a civil action in federal court for deprivation of his and other stockholders' preemptive rights by reason of a merger involving the company, allegedly effected through use of a false and misleading proxy statement. The complaint has two counts, one based on diversity and claiming a breach of directors' fiduciary duty to stockholders and the other alleging a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 16","1":"13"}},{"t":"case","label":"Janus v. Am. Fed’n of State, Cnty., & Mun. Emps.","cite":"138 S. Ct. 2448","y":2018,"id":"2017/16-1466","sc":1,"sum":"The Court decided the State of Illinois’ extraction of agency fees from nonconsenting public-sector employees violates the First Amendment; Abood v. Detroit Bd. of Ed., 431 U.S. 209 (1977), which held otherwise, was overruled.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Jesner v. Arab Bank, PLC","cite":"138 S. Ct. 1386","y":2018,"id":"2017/16-499","sc":1,"op":1,"sum":"The Court held that the Alien Tort Statute does not permit lawsuits against corporations.","sumSrc":"Oyez","by":{"0":"18","2":"5"}},{"t":"case","label":"Jones v. Sposato","cite":"783 F. App’x 214","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/783/214/","by":{"0":"26"}},{"t":"case","label":"Jud. Watch, Inc. v. Rossotti","cite":"317 F.3d 401","y":2003,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/317/401/","by":{"0":"33"}},{"t":"case","label":"Levin v. United States","cite":"568 U.S. 503","y":2013,"id":"2012/11-1351","sc":1,"sum":"The Court held that the Gonzalez Act made an exception to the Federal Tort Claims Act by saying that a claim of the intentional tort of battery may be brought against an armed forces physician.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Loumiet v. United States","cite":"948 F.3d 376","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/948/376/","by":{"0":"26","1":"21"}},{"t":"case","label":"Mack v. Yost","cite":"968 F.3d 311","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/968/311/","by":{"0":"26, 28","1":"21"}},{"t":"case","label":"Minneci v. Pollard","cite":"565 U.S. 118","y":2012,"id":"2011/10-1104","sc":1,"op":3,"sum":"Rejecting Bivens action for Eighth Amendment violations against employees of a privately operated federal prison because “state tort law authorizes adequate alternative damages actions—actions that provide both signifcant deterrence and compensation”.","sumSrc":"opinion","by":{"0":"33","1":"13, 26","2":"17, 23"}},{"t":"case","label":"Nestlè USA, Inc. v. Doe","cite":"141 S. Ct. 1931","y":2021,"id":"2020/19-416","sc":1,"sum":"To plead facts sufficient to support a domestic application of the Alien Tort Statute, 28 U. S. C. §1350, plaintiffs must allege more domestic conduct than general corporate activity; the Ninth Circuit’s contrary holding is reversed, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28","1":"15","2":"6, 10"}},{"t":"case","label":"Oliva v. Nivar","cite":"973 F.3d 438","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/973/438/","op":1,"by":{"0":"passim","2":"18, 20"}},{"t":"case","label":"Patton v. Kimble","cite":"847 F. App’x 196","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/847/196/","by":{"0":"6"}},{"t":"case","label":"Reichle v. Howards","cite":"566 U.S. 658","y":2012,"id":"2011/11-262","sc":1,"op":2,"sum":"The Court held that police officers and federal agents cannot be sued for violating someone’s rights, as long as the right that was supposedly violated was not formally recognized to exist at the time the officers acted.","sumSrc":"Oyez","by":{"0":"26","1":"17, 20, 23","2":"11"}},{"t":"case","label":"Schweiker v. Chilicky","cite":"487 U.S. 412","y":1988,"id":"1987/86-1781","sc":1,"op":11,"sum":"The Court held that when a government employee violates a citizen’s legal rights, that citizen is not allowed to pursue monetary damages as compensation when the violated statute does not contain monetary damages as a possible remedy.","sumSrc":"Oyez","by":{"0":"20, 34, 35, 38","1":"13, 24, 26, 27","2":"9, 17, 23"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Staats v. Brown","cite":"991 P.2d 615","y":2000,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/991/615/","by":{"0":"40"}},{"t":"case","label":"Tex. Indus., Inc. v. Radcliff Materials, Inc.","cite":"451 U.S. 630","y":1981,"id":"1980/79-1144","sc":1,"sum":"There is no basis in federal statutory or common law for allowing federal courts to fashion the right to contribution urged by petitioner.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16","2":"5"}},{"t":"case","label":"Trump v. Hawaii","cite":"138 S. Ct. 2392","y":2018,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Tun-Cos v. Perrotte","cite":"922 F.3d 514","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/922/514/","by":{"0":"29, 36, 38, 39","1":"30"}},{"t":"case","label":"United States v. Arvizu","cite":"534 U.S. 266","y":2002,"id":"2001/00-1519","sc":1,"op":7,"sum":"Noting that remedies available to the plaintiff were “at least as great, and in many respects greater, than anything that could be had under Page Proof Pending Publication Bivens”.","sumSrc":"opinion","by":{"0":"5"}},{"t":"case","label":"United States v. Brugman","cite":"364 F.3d 613","y":2004,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/364/613/","by":{"0":"35"}},{"t":"case","label":"United States v. Cortez","cite":"449 U.S. 411","y":1981,"id":"1980/79-404","sc":1,"sum":"The objective facts and circumstantial evidence justified the investigative stop of respondents' vehicle.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4"}},{"t":"case","label":"United States v. Montoya de Hernandez","cite":"473 U.S. 531","y":1985,"id":"1984/84-755","sc":1,"ar":1,"sum":"The Supreme Court held that detention of a traveler at an international border is justified if customs agents reasonably suspect that the traveler is smuggling illegal drugs in their body. The facts in this case supported that reasonable suspicion. Given the manner in which the drugs were concealed, Montoya de Hernandez’s detention was not unreasonably long.","sumSrc":"Oyez","by":{"0":"36, 37","1":"29","2":"19"}},{"t":"case","label":"United States v. S.A. Empresa de Viacao Aerea Rio Grandense","cite":"467 U.S. 797","y":1984,"id":"1983/82-1349","sc":1,"sum":"Government liability under the FTCA is limited by the discretionary function exception of 28 U.S.C. Section 2680(a), which provides that the federal government may not be held liable for \"[a]ny claim based upon an act or omission of an employee of the Government . . . based upon the exercise or performance or the failure to exercise or perform a discretionary function . . . whether or not the discretion involved be abused.\" The FAA's decision to institute the \"spot-check\" program to monitor compliance with its minimum safety standards was clearly discretionary and protected by Section 2680(a).","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"United States v. Soto-Barraza","cite":"947 F.3d 1111","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/947/1111/","by":{"0":"5"}},{"t":"case","label":"Vanderklok v. United States","cite":"868 F.3d 189","y":2017,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/868/189/","by":{"0":"26","1":"21, 26"}},{"t":"case","label":"Waksmundski v. Williams","cite":"727 F. App’x 818","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/727/818/","by":{"0":"26"}},{"t":"case","label":"Watkins v. Three Admin. Remedy Coordinators","cite":"998 F.3d 682","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/998/682/","op":8,"by":{"0":"26"}},{"t":"case","label":"Wilkie v. Robbins","cite":"551 U.S. 537","y":2007,"id":"2006/06-219","sc":1,"op":8,"sum":"Noting that the Bivens inquiry asks courts to “weig[h] reasons for and against the creation of a new cause of action”.","sumSrc":"opinion","by":{"0":"32, 33, 34, 39","1":"13, 21, 26, 27","2":"9, 13, 17, 18"}},{"t":"case","label":"Wilson v. Libby","cite":"535 F.3d 697","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/535/697/","by":{"0":"34"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"137 S. Ct. 1843","y":2017,"id":"2016/15-1358","sc":1,"op":54,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"usc","label":"5 U.S.C. § 552a","url":"https://www.law.cornell.edu/uscode/text/5/552a","subs":["(a)(4)","(i)(1)"],"stext":{"head":"§552a. Records maintained on individuals","paras":[[0,"(a) Definitions.—For purposes of this section—"],[1,"(1) the term \"agency\" means agency as defined in section 552(e) 1 of this title;"],[1,"(2) the term \"individual\" means a citizen of the United States or an alien lawfully admitted for permanent residence;"],[1,"(3) the term \"maintain\" includes maintain, collect, use, or disseminate;"],[1,"(4) the term \"record\" means any item, collection, or grouping of information about an individual that is maintained by an agency, including, but not limited to, his education, financial transactions, medical history, and criminal or employment history and that contains his name, or the identifying number, symbol, or other identifying particular assigned to the individual, such as a finger or voice print or a photograph;"],[1,"(5) the term \"system of records\" means a group of any records under the control of any agency from which information is retrieved by the name of the individual or by some identifying number, symbol, or other identifying particular assigned to the individual;"],[1,"(6) the term \"statistical record\" means a record in a system of records maintained for statistical research or reporting purposes only and not used in whole or in part in making any determination about an identifiable individual, except as provided by section 8 of title 13;"],[1,"(7) the term \"routine use\" means, with respect to the disclosure of a record, the use of such record for a purpose which is compatible with the purpose for which it was collected;"],[1,"(8) the term \"matching program\"—"],[2,"(A) means any computerized comparison of—"],[3,"(i) two or more automated systems of records or a system of records with non-Federal records for the purpose of—"],[4,"(I) establishing or verifying the eligibility of, or continuing compliance with statutory and regulatory requirements by, applicants for, recipients or beneficiaries of, participants in, or providers of services with respect to, cash or in-kind assistance or payments under Federal benefit programs, or"],[4,"(II) recouping payments or delinquent debts under such Federal benefit programs, or"],[3,"(ii) two or more automated Federal personnel or payroll systems of records or a system of Federal personnel or payroll records with non-Federal records,"],[2,"(B) but does not include—"],[3,"(i) matches performed to produce aggregate statistical data without any personal identifiers;"],[3,"(ii) matches performed to support any research or statistical project, the specific data of which may not be used to make decisions concerning the rights, benefits, or privileges of specific individuals;"],[3,"(iii) matches performed, by an agency (or component thereof) which performs as its principal function any activity pertaining to the enforcement of criminal laws, subsequent to the initiation of a specific criminal or civil law enforcement investigation of a named person or persons for the purpose of gathering evidence against such person or persons;"],[3,"(iv) matches of tax information (I) pursuant to section 6103(d) of the Internal Revenue Code of 1986, (II) for purposes of tax administration as defined in section 6103(b)(4) of such Code, (III) for the purpose of intercepting a tax refund due an individual under authority granted by section 404(e), 464, or 1137 of the Social Security Act; or (IV) for the purpose of intercepting a tax refund due an individual under any other tax refund intercept program authorized by statute which has been determined by the Director of the Office of Management and Budget to contain verification, notice, and hearing requirements that are substantially similar to the procedures in section 1137 of the Social Security Act;"],[3,"(v) matches—"],[4,"(I) using records predominantly relating to Federal personnel, that are performed for routine administrative purposes (subject to guidance provided by the Director of the Office of Management and Budget pursuant to subsection (v)); or"],[4,"(II) conducted by an agency using only records from systems of records maintained by that agency;"],[0,"if the purpose of the match is not to take any adverse financial, personnel, disciplinary, or other adverse action against Federal personnel;"],[3,"(vi) matches performed for foreign counterintelligence purposes or to produce background checks for security clearances of Federal personnel or Federal contractor personnel;"],[3,"(vii) matches performed incident to a levy described in section 6103(k)(8) of the Internal Revenue Code of 1986;"],[3,"(viii) matches performed pursuant to section 202(x)(3) or 1611(e)(1) of the Social Security Act (42 U.S.C. 402(x)(3), 1382(e)(1));"],[3,"(ix) matches performed by the Secretary of Health and Human Services or the Inspector General of the Department of Health and Human Services with respect to potential fraud, waste, and abuse, including matches of a system of records with non-Federal records; or"],[3,"(x) matches performed pursuant to section 3(d)(4) of the Achieving a Better Life Experience Act of 2014; 1"],[1,"(9) the term \"recipient agency\" means any agency, or contractor thereof, receiving records contained in a system of records from a source agency for use in a matching program;"],[1,"(10) the term \"non-Federal agency\" means any State or local government, or agency thereof, which receives records contained in a system of records from a source agency for use in a matching program;"],[1,"(11) the term \"source agency\" means any agency which discloses records contained in a system of records to be used in a matching program, or any State or local government, or agency thereof, which discloses records to be used in a matching program;"],[1,"(12) the term \"Federal benefit program\" means any program administered or funded by the Federal Government, or by any agent or State on behalf of the Federal Government, providing cash or in-kind assistance in the form of payments, grants, loans, or loan guarantees to individuals; and"],[1,"(13) the term \"Federal personnel\" means officers and employees of the Government of the United States, members of the uniformed services (including members of the Reserve Components), individuals entitled to receive immediate or deferred retirement benefits under any retirement program of the Government of the United States (including survivor benefits)."],[0,"(b) Conditions of Disclosure.—No agency shall disclose any record which is contained in a system of records by any means of communication to any person, or to another agency, except pursuant to a written request by, or with the prior written consent of, the individual to whom the record pertains, unless disclosure of the record would be—"],[1,"(1) to those officers and employees of the agency which maintains the record who have a need for the record in the performance of their duties;"],[1,"(2) required under section 552 of this title;"],[1,"(3) for a routine use as defined in subsection (a)(7) of this section and described under subsection (e)(4)(D) of this section;"],[1,"(4) to the Bureau of the Census for purposes of planning or carrying out a census or survey or related activity pursuant to the provisions of title 13;"],[1,"(5) to a recipient who has provided the agency with advance adequate written assurance that the record will be used solely as a statistical research or reporting record, and the record is to be transferred in a form that is not individually identifiable;"],[1,"(6) to the National Archives and Records Administration as a record which has sufficient historical or other value to warrant its continued preservation by the United States Government, or for evaluation by the Archivist of the United States or the designee of the Archivist to determine whether the record has such value;"],[1,"(7) to another agency or to an instrumentality of any governmental jurisdiction within or under the control of the United States for a civil or criminal law enforcement activity if the activity is authorized by law, and if the head of the agency or instrumentality has made a written request to the agency which maintains the record specifying the particular portion desired and the law enforcement activity for which the record is sought;"],[1,"(8) to a person pursuant to a showing of compelling circumstances affecting the health or safety of an individual if upon such disclosure notification is transmitted to the last known address of such individual;"],[1,"(9) to either House of Congress, or, to the extent of matter within its jurisdiction, any committee or subcommittee thereof, any joint committee of Congress or subcommittee of any such joint committee;"],[1,"(10) to the Comptroller General, or any of his authorized representatives, in the course of the performance of the duties of the Government Accountability Office;"],[1,"(11) to the Director of the Congressional Budget Office, or any authorized representative of the Director, in the course of performance of the duties of the Congressional Budget Office;"],[1,"(12) pursuant to the order of a court of competent jurisdiction; or"],[1,"(13) to a consumer reporting agency in accordance with section 3711(e) of title 31."],[0,"(c) Accounting of Certain Disclosures.—Each agency, with respect to each system of records under its control, shall—"],[1,"(1) except for disclosures made under subsections (b)(1) or (b)(2) of this section, keep an accurate accounting of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/552a?type=usc&year=mostrecent&link-type=html"},"head":"§552a. Records maintained on individuals","tname":"Government Organization and Employees","by":{"0":"34","1":"25, 25, 25"}},{"t":"usc","label":"6 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/6/211","subs":["(c)(5)","(c)(8)(B)","(e)(1)","(e)(3)(A)","(e)(3)(B)"],"stext":{"head":"§211. Establishment of U.S. Customs and Border Protection; Commissioner, Deputy Commissioner, and operational offices","paras":[[0,"(a) In general"],[0,"There is established in the Department an agency to be known as U.S. Customs and Border Protection."],[0,"(b) Commissioner of U.S. Customs and Border Protection"],[0,"(1) In general"],[1,"There shall be at the head of U.S. Customs and Border Protection a Commissioner of U.S. Customs and Border Protection (in this section referred to as the \"Commissioner\")."],[0,"(2) Committee referral"],[1,"As an exercise of the rulemaking power of the Senate, any nomination for the Commissioner submitted to the Senate for confirmation, and referred to a committee, shall be referred to the Committee on Finance."],[0,"(c) Duties"],[0,"The Commissioner shall—"],[1,"(1) coordinate and integrate the security, trade facilitation, and trade enforcement functions of U.S. Customs and Border Protection;"],[1,"(2) ensure the interdiction of persons and goods illegally entering or exiting the United States;"],[1,"(3) facilitate and expedite the flow of legitimate travelers and trade;"],[1,"(4) direct and administer the commercial operations of U.S. Customs and Border Protection, and the enforcement of the customs and trade laws of the United States;"],[1,"(5) detect, respond to, and interdict terrorists, drug smugglers and traffickers, human smugglers and traffickers, and other persons who may undermine the security of the United States, in cases in which such persons are entering, or have recently entered, the United States;"],[1,"(6) safeguard the borders of the United States to protect against the entry of dangerous goods;"],[1,"(7) ensure the overall economic security of the United States is not diminished by efforts, activities, and programs aimed at securing the homeland;"],[1,"(8) in coordination with U.S. Immigration and Customs Enforcement and United States Citizenship and Immigration Services, enforce and administer all immigration laws, as such term is defined in paragraph (17) of section 1101(a) of title 8, including—"],[2,"(A) the inspection, processing, and admission of persons who seek to enter or depart the United States; and"],[2,"(B) the detection, interdiction, removal, departure from the United States, short-term detention, and transfer of persons unlawfully entering, or who have recently unlawfully entered, the United States;"],[1,"(9) develop and implement screening and targeting capabilities, including the screening, reviewing, identifying, and prioritizing of passengers and cargo across all international modes of transportation, both inbound and outbound;"],[1,"(10) in coordination with the Secretary, deploy technology to collect the data necessary for the Secretary to administer the biometric entry and exit data system pursuant to section 1365b of title 8;"],[1,"(11) enforce and administer the laws relating to agricultural import and entry inspection referred to in section 231 of this title;"],[1,"(12) in coordination with the Under Secretary for Management of the Department, ensure U.S. Customs and Border Protection complies with Federal law, the Federal Acquisition Regulation, and the Department's acquisition management directives for major acquisition programs of U.S. Customs and Border Protection;"],[1,"(13) ensure that the policies and regulations of U.S. Customs and Border Protection are consistent with the obligations of the United States pursuant to international agreements;"],[1,"(14) enforce and administer—"],[2,"(A) the Container Security Initiative program under section 205 of the Security and Accountability for Every Port Act of 2006 (6 U.S.C. 945); and"],[2,"(B) the Customs–Trade Partnership Against Terrorism program under subtitle B of title II of such Act (6 U.S.C. 961 et seq.);"],[1,"(15) conduct polygraph examinations in accordance with section 221(1) of this title;"],[1,"(16) establish the standard operating procedures described in subsection (k);"],[1,"(17) carry out the training required under subsection (l);"],[1,"(18) carry out section 218 of this title, relating to the issuance of Asia-Pacific Economic Cooperation Business Travel Cards; and"],[1,"(19) carry out other duties and powers prescribed by law or delegated by the Secretary."],[0,"(d) Deputy Commissioner"],[0,"There shall be in U.S. Customs and Border Protection a Deputy Commissioner who shall assist the Commissioner in the management of U.S. Customs and Border Protection."],[0,"(e) U.S. Border Patrol"],[0,"(1) In general"],[1,"There is established in U.S. Customs and Border Protection the U.S. Border Patrol."],[0,"(2) Chief"],[1,"There shall be at the head of the U.S. Border Patrol a Chief, who shall—"],[2,"(A) be at the level of Executive Assistant Commissioner within U.S. Customs and Border Protection; and"],[2,"(B) report to the Commissioner."],[0,"(3) Duties"],[1,"The U.S. Border Patrol shall—"],[2,"(A) serve as the law enforcement office of U.S. Customs and Border Protection with primary responsibility for interdicting persons attempting to illegally enter or exit the United States or goods being illegally imported into or exported from the United States at a place other than a designated port of entry;"],[2,"(B) deter and prevent the illegal entry of terrorists, terrorist weapons, persons, and contraband; and"],[2,"(C) carry out other duties and powers prescribed by the Commissioner."],[0,"(f) Air and Marine Operations"],[0,"(1) In general"],[1,"There is established in U.S. Customs and Border Protection an office known as Air and Marine Operations."],[0,"(2) Executive Assistant Commissioner"],[1,"There shall be at the head of Air and Marine Operations an Executive Assistant Commissioner, who shall report to the Commissioner."],[0,"(3) Duties"],[1,"Air and Marine Operations shall—"],[2,"(A) serve as the law enforcement office within U.S. Customs and Border Protection with primary responsibility to detect, interdict, and prevent acts of terrorism and the unlawful movement of people, illicit drugs, and other contraband across the borders of the United States in the air and maritime environment;"],[2,"(B) conduct joint aviation and marine operations with U.S. Immigration and Customs Enforcement;"],[2,"(C) conduct aviation and marine operations with international, Federal, State, and local law enforcement agencies, as appropriate;"],[2,"(D) administer the Air and Marine Operations Center established under paragraph (4); and"],[2,"(E) carry out other duties and powers prescribed by the Commissioner."],[0,"(4) Air and Marine Operations Center"],[0,"(A) In general"],[2,"There is established in Air and Marine Operations an Air and Marine Operations Center."],[0,"(B) Executive Director"],[2,"There shall be at the head of the Air and Marine Operations Center an Executive Director, who shall report to the Executive Assistant Commissioner of Air and Marine Operations."],[0,"(C) Duties"],[2,"The Air and Marine Operations Center shall—"],[3,"(i) manage the air and maritime domain awareness of the Department, as directed by the Secretary;"],[3,"(ii) monitor and coordinate the airspace for unmanned aerial systems operations of Air and Marine Operations in U.S. Customs and Border Protection;"],[3,"(iii) detect, identify, and coordinate a response to threats to national security in the air domain, in coordination with other appropriate agencies, as determined by the Executive Assistant Commissioner;"],[3,"(iv) provide aviation and marine support to other Federal, State, tribal, and local agencies; and"],[3,"(v) carry out other duties and powers prescribed by the Executive Assistant Commissioner."],[0,"(g) Office of Field Operations"],[0,"(1) In general"],[1,"There is established in U.S. Customs and Border Protection an Office of Field Operations."],[0,"(2) Executive Assistant Commissioner"],[1,"There shall be at the head of the Office of Field Operations an Executive Assistant Commissioner, who shall report to the Commissioner."],[0,"(3) Duties"],[1,"The Office of Field Operations shall coordinate the enforcement activities of U.S. Customs and Border Protection at United States air, land, and sea ports of entry to—"],[2,"(A) deter and prevent terrorists and terrorist weapons from entering the United States at such ports of entry;"],[2,"(B) conduct inspections at such ports of entry to safeguard the United States from terrorism and illegal entry of persons;"],[2,"(C) prevent illicit drugs, agricultural pests, and contraband from entering the United States;"],[2,"(D) in coordination with the Commissioner, facilitate and expedite the flow of legitimate travelers and trade;"],[2,"(E) administer the National Targeting Center established under paragraph (4);"],[2,"(F) coordinate with the Executive Assistant Commissioner for the Office of Trade with respect to the trade facilitation and trade enforcement activities of U.S. Customs and Border Protection; and"],[2,"(G) carry out other duties and powers prescribed by the Commissioner."],[0,"(4) National Targeting Center"],[0,"(A) In general"],[2,"There is established in the Office of Field Operations a National Targeting Center."],[0,"(B) Executive Director"],[2,"There shall be at the head of the National Targeting Center an Executive Director, who shall report to the Executive Assistant Commissioner of the Office of Field Operations."],[0,"(C) Duties"],[2,"The National Targeting Center shall—"],[3,"(i) serve as the primary forum for targeting operations within U.S. Customs and Border Protection to collect and analyze traveler and cargo information in advance of arrival in the United States to identify and address security risks and strengthen trade enforcement;"],[3,"(ii) identify, review, and target travelers and cargo for examination;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/211?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§211. Establishment of U.S. Customs and Border Protection; Commissioner, Deputy Commissioner, and operational offices","tname":"Domestic Security","by":{"0":"4, 30","1":"28, 28, 29, 29, 29","2":"20, 21"}},{"t":"usc","label":"8 U.S.C. § 1357","url":"https://www.law.cornell.edu/uscode/text/8/1357","subs":["(a)(1)"],"stext":{"head":"§1357. Powers of immigration officers and employees","paras":[[0,"(a) Powers without warrant"],[0,"Any officer or employee of the Service authorized under regulations prescribed by the Attorney General shall have power without warrant—"],[1,"(1) to interrogate any alien or person believed to be an alien as to his right to be or to remain in the United States;"],[1,"(2) to arrest any alien who in his presence or view is entering or attempting to enter the United States in violation of any law or regulation made in pursuance of law regulating the admission, exclusion, expulsion, or removal of aliens, or to arrest any alien in the United States, if he has reason to believe that the alien so arrested is in the United States in violation of any such law or regulation and is likely to escape before a warrant can be obtained for his arrest, but the alien arrested shall be taken without unnecessary delay for examination before an officer of the Service having authority to examine aliens as to their right to enter or remain in the United States;"],[1,"(3) within a reasonable distance from any external boundary of the United States, to board and search for aliens any vessel within the territorial waters of the United States and any railway car, aircraft, conveyance, or vehicle, and within a distance of twenty-five miles from any such external boundary to have access to private lands, but not dwellings, for the purpose of patrolling the border to prevent the illegal entry of aliens into the United States;"],[1,"(4) to make arrests for felonies which have been committed and which are cognizable under any law of the United States regulating the admission, exclusion, expulsion, or removal of aliens, if he has reason to believe that the person so arrested is guilty of such felony and if there is likelihood of the person escaping before a warrant can be obtained for his arrest, but the person arrested shall be taken without unnecessary delay before the nearest available officer empowered to commit persons charged with offenses against the laws of the United States; and"],[1,"(5) to make arrests—"],[2,"(A) for any offense against the United States, if the offense is committed in the officer's or employee's presence, or"],[2,"(B) for any felony cognizable under the laws of the United States, if the officer or employee has reasonable grounds to believe that the person to be arrested has committed or is committing such a felony,"],[1,"if the officer or employee is performing duties relating to the enforcement of the immigration laws at the time of the arrest and if there is a likelihood of the person escaping before a warrant can be obtained for his arrest."],[0,"Under regulations prescribed by the Attorney General, an officer or employee of the Service may carry a firearm and may execute and serve any order, warrant, subpoena, summons, or other process issued under the authority of the United States. The authority to make arrests under paragraph (5)(B) shall only be effective on and after the date on which the Attorney General publishes final regulations which (i) prescribe the categories of officers and employees of the Service who may use force (including deadly force) and the circumstances under which such force may be used, (ii) establish standards with respect to enforcement activities of the Service, (iii) require that any officer or employee of the Service is not authorized to make arrests under paragraph (5)(B) unless the officer or employee has received certification as having completed a training program which covers such arrests and standards described in clause (ii), and (iv) establish an expedited, internal review process for violations of such standards, which process is consistent with standard agency procedure regarding confidentiality of matters related to internal investigations."],[0,"(b) Administration of oath; taking of evidence"],[0,"Any officer or employee of the Service designated by the Attorney General, whether individually or as one of a class, shall have power and authority to administer oaths and to take and consider evidence concerning the privilege of any person to enter, reenter, pass through, or reside in the United States, or concerning any matter which is material or relevant to the enforcement of this chapter and the administration of the Service; and any person to whom such oath has been administered, (or who has executed an unsworn declaration, certificate, verification, or statement under penalty of perjury as permitted under section 1746 of title 28) under the provisions of this chapter, who shall knowingly or willfully give false evidence or swear (or subscribe under penalty of perjury as permitted under section 1746 of title 28) to any false statement concerning any matter referred to in this subsection shall be guilty of perjury and shall be punished as provided by section 1621 of title 18."],[0,"(c) Search without warrant"],[0,"Any officer or employee of the Service authorized and designated under regulations prescribed by the Attorney General, whether individually or as one of a class, shall have power to conduct a search, without warrant, of the person, and of the personal effects in the possession of any person seeking admission to the United States, concerning whom such officer or employee may have reasonable cause to suspect that grounds exist for denial of admission to the United States under this chapter which would be disclosed by such search."],[0,"(d) Detainer of aliens for violation of controlled substances laws"],[0,"In the case of an alien who is arrested by a Federal, State, or local law enforcement official for a violation of any law relating to controlled substances, if the official (or another official)—"],[1,"(1) has reason to believe that the alien may not have been lawfully admitted to the United States or otherwise is not lawfully present in the United States,"],[1,"(2) expeditiously informs an appropriate officer or employee of the Service authorized and designated by the Attorney General of the arrest and of facts concerning the status of the alien, and"],[1,"(3) requests the Service to determine promptly whether or not to issue a detainer to detain the alien,"],[0,"the officer or employee of the Service shall promptly determine whether or not to issue such a detainer. If such a detainer is issued and the alien is not otherwise detained by Federal, State, or local officials, the Attorney General shall effectively and expeditiously take custody of the alien."],[0,"(e) Restriction on warrantless entry in case of outdoor agricultural operations"],[0,"Notwithstanding any other provision of this section other than paragraph (3) of subsection (a), an officer or employee of the Service may not enter without the consent of the owner (or agent thereof) or a properly executed warrant onto the premises of a farm or other outdoor agricultural operation for the purpose of interrogating a person believed to be an alien as to the person's right to be or to remain in the United States."],[0,"(f) Fingerprinting and photographing of certain aliens"],[0,"(1) Under regulations of the Attorney General, the Commissioner shall provide for the fingerprinting and photographing of each alien 14 years of age or older against whom a proceeding is commenced under section 1229a of this title."],[0,"(2) Such fingerprints and photographs shall be made available to Federal, State, and local law enforcement agencies, upon request."],[0,"(g) Performance of immigration officer functions by State officers and employees"],[0,"(1) Notwithstanding section 1342 of title 31, the Attorney General may enter into a written agreement with a State, or any political subdivision of a State, pursuant to which an officer or employee of the State or subdivision, who is determined by the Attorney General to be qualified to perform a function of an immigration officer in relation to the investigation, apprehension, or detention of aliens in the United States (including the transportation of such aliens across State lines to detention centers), may carry out such function at the expense of the State or political subdivision and to the extent consistent with State and local law."],[0,"(2) An agreement under this subsection shall require that an officer or employee of a State or political subdivision of a State performing a function under the agreement shall have knowledge of, and adhere to, Federal law relating to the function, and shall contain a written certification that the officers or employees performing the function under the agreement have received adequate training regarding the enforcement of relevant Federal immigration laws."],[0,"(3) In performing a function under this subsection, an officer or employee of a State or political subdivision of a State shall be subject to the direction and supervision of the Attorney General."],[0,"(4) In performing a function under this subsection, an officer or employee of a State or political subdivision of a State may use Federal property or facilities, as provided in a written agreement between the Attorney General and the State or subdivision."],[0,"(5) With respect to each officer or employee of a State or political subdivision who is authorized to perform a function under this subsection, the specific powers and duties that may be, or are required to be, exercised or performed by the individual, the duration of the authority of the individual, and the position of the agency of the Attorney General who is required to supervise and direct the individual, shall be set forth in a written agreement between the Attorney General and the State or political subdivision."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1357?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1357. Powers of immigration officers and employees","tname":"Aliens and Nationality","by":{"0":"4, 37, 38","1":"29","2":"19, 20, 22"}},{"t":"usc","label":"18 U.S.C. § 242","url":"https://www.law.cornell.edu/uscode/text/18/242","stext":{"head":"§242. Deprivation of rights under color of law","paras":[[0,"Whoever, under color of any law, statute, ordinance, regulation, or custom, willfully subjects any person in any State, Territory, Commonwealth, Possession, or District to the deprivation of any rights, privileges, or immunities secured or protected by the Constitution or laws of the United States, or to different punishments, pains, or penalties, on account of such person being an alien, or by reason of his color, or race, than are prescribed for the punishment of citizens, shall be fined under this title or imprisoned not more than one year, or both; and if bodily injury results from the acts committed in violation of this section or if such acts include the use, attempted use, or threatened use of a dangerous weapon, explosives, or fire, shall be fined under this title or imprisoned not more than ten years, or both; and if death results from the acts committed in violation of this section or if such acts include kidnapping or an attempt to kidnap, aggravated sexual abuse, or an attempt to commit aggravated sexual abuse, or an attempt to kill, shall be fined under this title, or imprisoned for any term of years or for life, or both, or may be sentenced to death."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/242?type=usc&year=mostrecent&link-type=html"},"head":"§242. Deprivation of rights under color of law","tname":"Crimes and Criminal Procedure","by":{"0":"22, 35","1":"32","2":"9"}},{"t":"usc","label":"26 U.S.C. § 6213","url":"https://www.law.cornell.edu/uscode/text/26/6213","by":{"0":"34"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"2"}},{"t":"usc","label":"28 U.S.C. § 2679","url":"https://www.law.cornell.edu/uscode/text/28/2679","subs":["(b)(1)"],"stext":{"head":"§2679. Exclusiveness of remedy","paras":[[0,"(a) The authority of any federal agency to sue and be sued in its own name shall not be construed to authorize suits against such federal agency on claims which are cognizable under section 1346(b) of this title, and the remedies provided by this title in such cases shall be exclusive."],[0,"(b)(1) The remedy against the United States provided by sections 1346(b) and 2672 of this title for injury or loss of property, or personal injury or death arising or resulting from the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment is exclusive of any other civil action or proceeding for money damages by reason of the same subject matter against the employee whose act or omission gave rise to the claim or against the estate of such employee. Any other civil action or proceeding for money damages arising out of or relating to the same subject matter against the employee or the employee's estate is precluded without regard to when the act or omission occurred."],[0,"(2) Paragraph (1) does not extend or apply to a civil action against an employee of the Government—"],[1,"(A) which is brought for a violation of the Constitution of the United States, or"],[1,"(B) which is brought for a violation of a statute of the United States under which such action against an individual is otherwise authorized."],[0,"(c) The Attorney General shall defend any civil action or proceeding brought in any court against any employee of the Government or his estate for any such damage or injury. The employee against whom such civil action or proceeding is brought shall deliver within such time after date of service or knowledge of service as determined by the Attorney General, all process served upon him or an attested true copy thereof to his immediate superior or to whomever was designated by the head of his department to receive such papers and such person shall promptly furnish copies of the pleadings and process therein to the United States attorney for the district embracing the place wherein the proceeding is brought, to the Attorney General, and to the head of his employing Federal agency."],[0,"(d)(1) Upon certification by the Attorney General that the defendant employee was acting within the scope of his office or employment at the time of the incident out of which the claim arose, any civil action or proceeding commenced upon such claim in a United States district court shall be deemed an action against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant."],[0,"(2) Upon certification by the Attorney General that the defendant employee was acting within the scope of his office or employment at the time of the incident out of which the claim arose, any civil action or proceeding commenced upon such claim in a State court shall be removed without bond at any time before trial by the Attorney General to the district court of the United States for the district and division embracing the place in which the action or proceeding is pending. Such action or proceeding shall be deemed to be an action or proceeding brought against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant. This certification of the Attorney General shall conclusively establish scope of office or employment for purposes of removal."],[0,"(3) In the event that the Attorney General has refused to certify scope of office or employment under this section, the employee may at any time before trial petition the court to find and certify that the employee was acting within the scope of his office or employment. Upon such certification by the court, such action or proceeding shall be deemed to be an action or proceeding brought against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant. A copy of the petition shall be served upon the United States in accordance with the provisions of Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. In the event the petition is filed in a civil action or proceeding pending in a State court, the action or proceeding may be removed without bond by the Attorney General to the district court of the United States for the district and division embracing the place in which it is pending. If, in considering the petition, the district court determines that the employee was not acting within the scope of his office or employment, the action or proceeding shall be remanded to the State court."],[0,"(4) Upon certification, any action or proceeding subject to paragraph (1), (2), or (3) shall proceed in the same manner as any action against the United States filed pursuant to section 1346(b) of this title and shall be subject to the limitations and exceptions applicable to those actions."],[0,"(5) Whenever an action or proceeding in which the United States is substituted as the party defendant under this subsection is dismissed for failure first to present a claim pursuant to section 2675(a) of this title, such a claim shall be deemed to be timely presented under section 2401(b) of this title if—"],[1,"(A) the claim would have been timely had it been filed on the date the underlying civil action was commenced, and"],[1,"(B) the claim is presented to the appropriate Federal agency within 60 days after dismissal of the civil action."],[0,"(e) The Attorney General may compromise or settle any claim asserted in such civil action or proceeding in the manner provided in section 2677, and with the same effect."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2679?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2679. Exclusiveness of remedy","tname":"Judiciary and Judicial Procedure","by":{"0":"22, 23, 33","1":"26","2":"10, 16"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"14, 15, 21, 22","1":"12, 16, 24","2":"9, 22"}},{"t":"law","label":"Pub. L. No. 96-170","url":"https://www.govinfo.gov/link/statute/93/1284","by":{"0":"22"}},{"t":"law","label":"Pub. L. No. 99-603","url":"https://www.govinfo.gov/link/statute/100/3359","by":{"0":"39"}},{"t":"law","label":"Pub. L. No. 101-649","url":"https://www.govinfo.gov/link/statute/104/4978","by":{"0":"39"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"39"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"39"}},{"t":"law","label":"Pub. L. No. 104-317","url":"https://www.govinfo.gov/link/plaw/104/public/317","by":{"0":"22"}},{"t":"law","label":"Pub. L. No. 109-13","url":"https://www.govinfo.gov/link/plaw/109/public/13","by":{"0":"39"}},{"t":"reg","label":"5 C.F.R. § 731.202","url":"https://www.ecfr.gov/current/title-5/section-731.202","by":{"0":"35"}},{"t":"reg","label":"8 C.F.R. § 287.8","url":"https://www.ecfr.gov/current/title-8/section-287.8","by":{"0":"39"}},{"t":"reg","label":"28 C.F.R. § 14.2","url":"https://www.ecfr.gov/current/title-28/section-14.2","by":{"0":"40"}},{"t":"case","label":"Buenrostro v. Fajardo","cite":"770 Fed. Appx. 807","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./770/807/","by":{"1":"21"}},{"t":"case","label":"Chappell v. Wallace","cite":"462 U.S. 296","y":1983,"id":"1982/82-167","sc":1,"op":12,"sum":"Enlisted military personnel may not maintain a suit to recover damages from a superior officer for alleged constitutional violations. The special status of the military has required, the Constitution has contemplated, Congress has created, and this Court has long recognized two systems of justice: one for civilians and one for military personnel. The need for unhesitating and decisive action by military officers and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13, 29"}},{"t":"case","label":"Doe v. Chao","cite":"540 U.S. 614","y":2004,"id":"2003/02-1377","sc":1,"sum":"The Court reasoned that \"a straightforward textual analysis\" of the Privacy Act shows that the statute guarantees the $1000 minimum for victims of willful Privacy Act violations only in relation to \"actual damages sustained.\" Individuals subjected to an adverse effect - like the miners in this case - have \"injury enough to open the courthouse door, but without more\" have \"no cause of action for damages under the Privacy Act.\".","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"342 U.S. 580","y":1952,"id":"scdb/1951-056","sc":1,"by":{"1":"18"}},{"t":"case","label":"Maria S. v. Garza","cite":"912 F.3d 778","y":2019,"url":"https://www.courtlistener.com/c/F.3d/912/778/","by":{"1":"30"}},{"t":"case","label":"Nieves v. Bartlett","cite":"139 S. Ct. 1715","y":2019,"id":"2018/17-1174","sc":1,"op":1,"sum":"Because police officers had probable cause to arrest Bartlett, his First Amendment retaliatory arrest claim fails as a matter of law.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22","2":"13"}},{"t":"case","label":"Petzold v. Rostollan","cite":"946 F.3d 242","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/946/242/","sum":"Finding it “unlikely” that Bivens extends to prisoner’s claim of retaliatory placement in special housing unit.","sumSrc":"brief:1","by":{"1":"21"}},{"t":"case","label":"Tanzin v. Tanvir","cite":"141 S. Ct. 486","y":2020,"id":"2020/19-71","sc":1,"sum":"The Religious Freedom Restoration Act of 1993’s express remedies provision, see 42 U. S. C. §2000bb–1(c), permits litigants, when appropriate, to obtain money damages against federal officials in their individual capacities.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23"}},{"t":"case","label":"United States v. Delgado-Garcia","cite":"374 F.3d 1337","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/374/1337/","by":{"1":"28"}},{"t":"case","label":"United States v. Stanley","cite":"483 U.S. 669","y":1987,"id":"1986/86-393","sc":1,"op":9,"sum":"The Supreme Court held that the Court of Appeals did not have the jurisdiction to consider Stanley’s FTCA claims because they were not a part of the order that was originally appealed. The Court also held that the Court of Appeals took an unnecessarily narrow view of the Chappell decision by limiting it to an even greater extent than the FTCA waiver of governmental liability.","sumSrc":"Oyez","by":{"1":"13","2":"7, 16"}},{"t":"case","label":"Wood v. Moss","cite":"572 U.S. 744","y":2014,"id":"2013/13-115","sc":1,"op":2,"sum":"The Court held that Secret Service agents did not break any \"clearly established\" laws in their efforts to protect the President, and were thus protected by qualified immunity.","sumSrc":"Oyez","by":{"1":"20, 23","2":"11"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"1":"passim"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"1":"12"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"1":"12"}},{"t":"law","label":"Pub. L. No. 100-694","url":"https://www.govinfo.gov/link/statute/102/4563","by":{"1":"26"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(b)(1)"],"by":{"1":"33"}},{"t":"usc","label":"28 U.S.C. § 2675","url":"https://www.law.cornell.edu/uscode/text/28/2675","subs":["(a)"],"stext":{"head":"§2675. Disposition by federal agency as prerequisite; evidence","paras":[[0,"(a) An action shall not be instituted upon a claim against the United States for money damages for injury or loss of property or personal injury or death caused by the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment, unless the claimant shall have first presented the claim to the appropriate Federal agency and his claim shall have been finally denied by the agency in writing and sent by certified or registered mail. The failure of an agency to make final disposition of a claim within six months after it is filed shall, at the option of the claimant any time thereafter, be deemed a final denial of the claim for purposes of this section. The provisions of this subsection shall not apply to such claims as may be asserted under the Federal Rules of Civil Procedure by third party complaint, cross-claim, or counterclaim."],[0,"(b) Action under this section shall not be instituted for any sum in excess of the amount of the claim presented to the federal agency, except where the increased amount is based upon newly discovered evidence not reasonably discoverable at the time of presenting the claim to the federal agency, or upon allegation and proof of intervening facts, relating to the amount of the claim."],[0,"(c) Disposition of any claim by the Attorney General or other head of a federal agency shall not be competent evidence of liability or amount of damages."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2675?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2675. Disposition by federal agency as prerequisite; evidence","tname":"Judiciary and Judicial Procedure","by":{"1":"4"}},{"t":"usc","label":"28 U.S.C. § 2680","url":"https://www.law.cornell.edu/uscode/text/28/2680","subs":["(h)"],"by":{"1":"33"}},{"t":"usc","label":"42 U.S.C. § 2000bb-2","url":"https://www.law.cornell.edu/uscode/text/42/2000bb-2","subs":["(1)"],"by":{"1":"23"}},{"t":"usc","label":"5 U.S.C. § 7503","url":"https://www.law.cornell.edu/uscode/text/5/7503","by":{"1":"27"}},{"t":"usc","label":"5 U.S.C. § 7513","url":"https://www.law.cornell.edu/uscode/text/5/7513","by":{"1":"27"}},{"t":"usc","label":"6 U.S.C. § 111","url":"https://www.law.cornell.edu/uscode/text/6/111","subs":["(b)(1)(A)","(b)(1)(E)"],"by":{"1":"28, 28"}},{"t":"usc","label":"18 U.S.C. § 3663","url":"https://www.law.cornell.edu/uscode/text/18/3663","subs":["(a)(1)(A)"],"by":{"1":"32"}},{"t":"case","label":"Chavez v. United States","cite":"683 F.3d 1102","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/683/1102/","by":{"2":"22"}},{"t":"case","label":"Elhady v. Unidentified CBP Agents","cite":"18 F.4th 880","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/18/880/","by":{"2":"13, 18, 19, 21"}},{"t":"case","label":"Exxon Shipping Co. v. Baker","cite":"554 U.S. 471","y":2008,"id":"2007/07-219","sc":1,"sum":"On the second issue, a 5-4 majority held that judges are free to create remedies in maritime cases where Congress has not legislated in the area. However, this freedom can be lost if Congress passes legislation restraining such judicial activism. Justice David Souter delivered the opinion of the Court.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Florida v. Jardines","cite":"569 U.S. 1","y":2013,"id":"2012/11-564","sc":1,"sum":"The Court found that a police officer and narcotic-sniffing dog entering the porch of a home constitutes a search and, without a warrant, is a violation of the Fourth Amendment.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Grupo Mexicano de Desarrollo S.A. v. All. Bond Fund, Inc.","cite":"527 U.S. 308","y":1999,"id":"1998/98-231","sc":1,"sum":"The Court held that the District Court lacked the authority to issue a preliminary injunction preventing defendants being sued by creditors from disposing of their assets pending adjudication of the creditor's contract claim for monetary damages because such a remedy was historically unavailable from a court of equity.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Hemphill v. New York","cite":"142 S. Ct. 681","y":2022,"id":"2021/20-637","sc":1,"sum":"The trial court’s admission—over Hemphill’s objection—of the plea allocution transcript of an unavailable witness violated Hemphill’s Sixth Amendment right to confront the witnesses against him.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"18"}},{"t":"case","label":"Herring v. United States","cite":"555 U.S. 135","y":2009,"id":"2008/07-513","sc":1,"sum":"The Court found that a criminal defendant's Fourth Amendment rights were not violated when he was unlawfully searched due to isolated negligence of police and not \"systematic error or reckless disregard of constitutional requirements.\"","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Hicks v. Ferreyra","cite":"965 F.3d 302","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/965/302/","by":{"2":"12"}},{"t":"case","label":"INS v. FLRA","cite":"12 F.3d 882","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/12/882/","by":{"2":"12"}},{"t":"case","label":"Ioane v. Hodges","cite":"939 F.3d 945","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/939/945/","by":{"2":"12"}},{"t":"case","label":"Jacobs v. Alam","cite":"915 F.3d 1028","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/915/1028/","by":{"2":"12"}},{"t":"case","label":"Marbury v. Madison","cite":"1 Cranch 137","y":1803,"url":"https://www.courtlistener.com/c/Cranch/1/137/","ar":1,"by":{"2":"4, 8"}},{"t":"case","label":"Morales v. Chadbourne","cite":"793 F.3d 208","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/793/208/","by":{"2":"22"}},{"t":"case","label":"Santos v. Frederick Cnty. Bd. of Comm’rs","cite":"725 F.3d 451","y":2013,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/725/451/","by":{"2":"22"}},{"t":"case","label":"Smith v. Leber","cite":"209 P.2d 297","y":1949,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/209/297/","by":{"2":"16"}},{"t":"case","label":"United States v. Romero-Bustamente","cite":"337 F.3d 1104","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/337/1104/","by":{"2":"20"}},{"t":"case","label":"Whole Women’s Health v. Jackson","cite":"142 S. Ct. 522","y":2021,"id":"2021/21-463","sc":1,"sum":"A pre-enforcement challenge under the Federal Constitution to Texas Senate Bill 8—the Texas Heartbeat Act—may proceed past the motion to dismiss stage against certain of the named defendants but not others; the order of the District Court is affirmed in part and reversed in part, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"4, 5"}}]};